/* From Uiverse.io by ChristosMourgelas - Tags: radio */
.__UIV_SCOPE__ .radio-input {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.__UIV_SCOPE__ .value-radio {
  display: none;
}

.__UIV_SCOPE__ .value-radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 2px solid #4d4d4d;
  border-radius: 20px;
  color: #ccc;
  background-color: #333;
  cursor: pointer;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .value-radio:checked + .value-radio-label {
  border-color: #00b4ff;
  background-color: #00b4ff;
  color: #fff;
}

.__UIV_SCOPE__ .value-radio-label::before {
  content: '';
  display: inline-block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid #4d4d4d;
  transition: all 1s;
}

.__UIV_SCOPE__ .value-radio:checked + .value-radio-label::before {
  border-color: #0175a6;
  background-color: #ffffff;
}
